select is(public.apply_highgate_authoritative_location_correction('23b498ab-7fed-5fbc-9f21-c9bea51cdf46','00000000-0000-0000-0000-000000006001')->>'outcome','created','counselling correction created');
select is(public.apply_highgate_authoritative_location_correction('23b498ab-7fed-5fbc-9f21-c9bea51cdf46','00000000-0000-0000-0000-000000006001')->>'outcome','idempotent','correction is idempotent');
