select is((select count(*)::integer from public.resource_fact_evidence e join public.resource_fact_claims c on c.id=e.claim_id where c.resource_id='b980ad5f-6dfc-5c03-ab5e-bbaaaf3d499f' and e.source_authority=95),2,'OAT receives fixed authoritative source evidence');
