select is((public.supersede_highgate_human_qc_with_machine_initial('23b498ab-7fed-5fbc-9f21-c9bea51cdf46',(select id from public.authoritative_location_corrections where resource_id='23b498ab-7fed-5fbc-9f21-c9bea51cdf46'),'00000000-0000-0000-0000-000000006201',1,'00000000-0000-0000-0000-000000006001')).origin,'machine_initial','human QC supersedes only through bound correction and geocoder');
select is((select count(*)::integer from public.location_qc_review_snapshots where canonical_resource_id='23b498ab-7fed-5fbc-9f21-c9bea51cdf46' and origin='human_qc'),1,'human QC snapshot preserved');
select is((select count(*)::integer from public.resource_locations),0,'correction and QC do not create locations');
select is((select count(*)::integer from public.resource_locations where public_map),0,'correction and QC never publish');
